## 回溯算法模板

### 通用模板
```java
public void backtrack(参数列表) {
    if (终止条件) {
        收集结果;
        return;
    }

    for (选择 : 选择列表) {
        // 剪枝（可选）
        if (不满足约束) continue;

        // 做选择
        路径.add(选择);

        // 递归
        backtrack(参数列表);

        // 撤销选择
        路径.remove(选择);
    }
}
```

### 关键点
1. **路径**：已经做出的选择
2. **选择列表**：当前可以做的选择
3. **结束条件**：到达决策树底层，无法再做选择
4. **剪枝**：避免无效的搜索

## 经典回溯问题

### 1. 全排列（Permutations）
```java
public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    List<Integer> path = new ArrayList<>();
    boolean[] used = new boolean[nums.length];
    backtrack(nums, path, used, result);
    return result;
}

private void backtrack(int[] nums, List<Integer> path, 
                       boolean[] used, List<List<Integer>> result) {
    if (path.size() == nums.length) {
        result.add(new ArrayList<>(path));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        path.add(nums[i]);
        backtrack(nums, path, used, result);
        path.remove(path.size() - 1);
        used[i] = false;
    }
}
```

### 2. 组合（Combinations）
```java
public List<List<Integer>> combine(int n, int k) {
    List<List<Integer>> result = new ArrayList<>();
    List<Integer> path = new ArrayList<>();
    backtrack(n, k, 1, path, result);
    return result;
}

private void backtrack(int n, int k, int start, 
                       List<Integer> path, List<List<Integer>> result) {
    if (path.size() == k) {
        result.add(new ArrayList<>(path));
        return;
    }
    for (int i = start; i <= n; i++) {
        path.add(i);
        backtrack(n, k, i + 1, path, result);
        path.remove(path.size() - 1);
    }
}
```

### 3. 子集（Subsets）
```java
public List<List<Integer>> subsets(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    List<Integer> path = new ArrayList<>();
    backtrack(nums, 0, path, result);
    return result;
}

private void backtrack(int[] nums, int start, 
                       List<Integer> path, List<List<Integer>> result) {
    result.add(new ArrayList<>(path));
    for (int i = start; i < nums.length; i++) {
        path.add(nums[i]);
        backtrack(nums, i + 1, path, result);
        path.remove(path.size() - 1);
    }
}
```

## 剪枝技巧

### 什么是剪枝？
剪枝是在回溯过程中，提前判断某些分支不可能产生有效解，从而跳过这些分支，减少搜索空间。

### 常见剪枝方法

#### 1. 排序剪枝
```java
// 先排序，便于跳过重复元素
Arrays.sort(nums);
```

#### 2. 重复元素剪枝
```java
// 跳过重复元素
if (i > start && nums[i] == nums[i - 1]) continue;
```

#### 3. 可行性剪枝
```java
// 如果当前和已经超过目标，直接返回
if (currentSum > target) return;
```

#### 4. 最优性剪枝
```java
// 如果当前解不可能优于已知最优解，直接返回
if (currentResult >= bestResult) return;
```

### 示例：组合总和
```java
public List<List<Integer>> combinationSum(int[] candidates, int target) {
    List<List<Integer>> result = new ArrayList<>();
    Arrays.sort(candidates); // 排序剪枝
    backtrack(candidates, target, 0, new ArrayList<>(), result);
    return result;
}

private void backtrack(int[] candidates, int target, int start, 
                       List<Integer> path, List<List<Integer>> result) {
    if (target == 0) {
        result.add(new ArrayList<>(path));
        return;
    }
    for (int i = start; i < candidates.length; i++) {
        if (candidates[i] > target) break; // 可行性剪枝
        path.add(candidates[i]);
        backtrack(candidates, target - candidates[i], i, path, result);
        path.remove(path.size() - 1);
    }
}
```

// 回溯算法示例
import java.util.*;

public class BacktrackingBasics {

    // 1. 全排列
    public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        List<Integer> path = new ArrayList<>();
        boolean[] used = new boolean[nums.length];
        backtrackPermute(nums, path, used, result);
        return result;
    }

    private void backtrackPermute(int[] nums, List<Integer> path, 
                                  boolean[] used, List<List<Integer>> result) {
        if (path.size() == nums.length) {
            result.add(new ArrayList<>(path));
            return;
        }
        for (int i = 0; i < nums.length; i++) {
            if (used[i]) continue;
            used[i] = true;
            path.add(nums[i]);
            backtrackPermute(nums, path, used, result);
            path.remove(path.size() - 1);
            used[i] = false;
        }
    }

    // 2. 组合
    public List<List<Integer>> combine(int n, int k) {
        List<List<Integer>> result = new ArrayList<>();
        List<Integer> path = new ArrayList<>();
        backtrackCombine(n, k, 1, path, result);
        return result;
    }

    private void backtrackCombine(int n, int k, int start, 
                                  List<Integer> path, List<List<Integer>> result) {
        if (path.size() == k) {
            result.add(new ArrayList<>(path));
            return;
        }
        for (int i = start; i <= n; i++) {
            path.add(i);
            backtrackCombine(n, k, i + 1, path, result);
            path.remove(path.size() - 1);
        }
    }

    // 3. 子集
    public List<List<Integer>> subsets(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        List<Integer> path = new ArrayList<>();
        backtrackSubsets(nums, 0, path, result);
        return result;
    }

    private void backtrackSubsets(int[] nums, int start, 
                                  List<Integer> path, List<List<Integer>> result) {
        result.add(new ArrayList<>(path));
        for (int i = start; i < nums.length; i++) {
            path.add(nums[i]);
            backtrackSubsets(nums, i + 1, path, result);
            path.remove(path.size() - 1);
        }
    }

    // 4. N皇后
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> result = new ArrayList<>();
        char[][] board = new char[n][n];
        for (char[] row : board) Arrays.fill(row, '.');
        backtrackNQueens(board, 0, result);
        return result;
    }

    private void backtrackNQueens(char[][] board, int row, 
                                  List<List<String>> result) {
        if (row == board.length) {
            List<String> solution = new ArrayList<>();
            for (char[] r : board) {
                solution.add(new String(r));
            }
            result.add(solution);
            return;
        }
        int n = board.length;
        for (int col = 0; col < n; col++) {
            if (!isValid(board, row, col)) continue;
            board[row][col] = 'Q';
            backtrackNQueens(board, row + 1, result);
            board[row][col] = '.';
        }
    }

    private boolean isValid(char[][] board, int row, int col) {
        int n = board.length;
        // 检查列
        for (int i = 0; i < row; i++) {
            if (board[i][col] == 'Q') return false;
        }
        // 检查左上对角线
        for (int i = row - 1, j = col - 1; i >= 0 && j >= 0; i--, j--) {
            if (board[i][j] == 'Q') return false;
        }
        // 检查右上对角线
        for (int i = row - 1, j = col + 1; i >= 0 && j < n; i--, j++) {
            if (board[i][j] == 'Q') return false;
        }
        return true;
    }

    // 5. 单词搜索
    public boolean exist(char[][] board, String word) {
        int rows = board.length, cols = board[0].length;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (backtrackWordSearch(board, word, i, j, 0)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean backtrackWordSearch(char[][] board, String word, 
                                        int row, int col, int index) {
        if (index == word.length()) return true;
        if (row < 0 || row >= board.length || 
            col < 0 || col >= board[0].length ||
            board[row][col] != word.charAt(index)) {
            return false;
        }
        char temp = board[row][col];
        board[row][col] = '#'; // 标记已访问
        boolean found = backtrackWordSearch(board, word, row + 1, col, index + 1) ||
                       backtrackWordSearch(board, word, row - 1, col, index + 1) ||
                       backtrackWordSearch(board, word, row, col + 1, index + 1) ||
                       backtrackWordSearch(board, word, row, col - 1, index + 1);
        board[row][col] = temp; // 撤销标记
        return found;
    }
}
